te": "2026-10", "round": "第二轮融资", "amount": "约1000亿元"}, {"inv": "梁文锋个人约200亿元，腾讯约100亿元、宁德时代约50亿元、网易/京东/砺思/IDG各约30亿元，国家人工智能产业投资基金", "date": "2026-06", "round": "首轮外部融资", "amount": "约510亿元"}, {"inv": "幻方量化（母公司），梁文锋自有资金及幻方体系支撑", "date": "2015", "round": "自筹（非外部融资）"}], "industry": "ai", "valuation": 5000, "latestTech": "年化营收运行率突破 10 亿美元；API 涨价后客户未流失；V4 系列支撑低成本推理", "execChanges": [], "lastFunding": "2026-10", "latestFunding": "2026-10 · 第二轮约 1000 亿元", "investorsStructured": [{"date": "2026-06", "kind": "cvc", "name": "宁德时代", "note": "第二轮增资约100亿元并领投", "role": "lead", "round": "首轮外部融资"}, {"date": "2026-06", "kind": "other", "name": "梁文锋", "note": "创始人个人出资约200亿元，最大单一股东", "role": "lead", "round": "首轮外部融资"}, {"date": "2026-06", "kind": "cvc", "name": "腾讯", "note": "第二轮继续领投", "role": "lead", "round": "首轮外部融资"}, {"date": "2026-06", "kind": "gov", "name": "国家人工智能产业投资基金", "role": "strategic", "round": "首轮外部融资"}, {"date": "2026-10", "kind": "pe", "name": "CPE源峰", "role": "follow", "round": "第二轮融资"}, {"date": "2026-06", "kind": "vc", "name": "IDG资本", "role": "follow", "round": "首轮外部融资"}, {"date": "2026-10", "kind": "cvc", "name": "中芯聚源", "role": "follow", "round": "第二轮融资"}, {"date": "2026-06", "kind": "cvc", "name": "京东", "role": "follow", "round": "首轮外部融资"}, {"date": "2026-10", "kind": "cvc", "name": "吉利", "role": "follow", "round": "第二轮融资"}, {"date": "2026-10", "kind": "vc", "name": "君联资本", "role": "follow", "round": "第二轮融资"}, {"date": "2026-06", "kind": "cvc", "name": "网易", "role": "follow", "round": "首轮外部融资"}]}}$json$::jsonb,
