-- 2) 辉羲智能：新增
INSERT INTO research_companies (name, code, industry, seg, listed, round, last_funding, data)
VALUES (
  "辉羲智能", "—", "semiconductor", "design", false, "B 轮", "2026-10",
  $json${"name": "辉羲智能", "code": "—", "industry": "semiconductor", "seg": "design", "listed": false, "round": "B 轮", "last_funding": "2026-10", "data": {"seg": "design", "code": "—", "desc": "具身智能大算力芯片与计算平台，自研光至 R1（500 TOPS）、RISE 平台与 RhinoVLA 模型，已用于智元精灵 G2。", "name": "辉羲智能", "tech": [{"date": "2022-04", "kind": "公司", "title": "北京辉羲科技成立，总部北京亦庄"}, {"date": "2026", "kind": "产品动态", "title": "光至 R1 芯片与 RISE 平台量产，用于智元精灵 G2，产线作业成功率 99.99%"}, {"date": "2026-10", "kind": "资本", "title": "完成 Pre-B+ 及 B 轮约 17 亿元，年内累计融资超 25 亿元"}], "round": "B 轮", "detail": "【定位】北京辉羲科技股份有限公司（辉羲智能），2022-04 成立，总部北京亦庄（大兴），定位具身智能计算平台供应商。技术体系为 RPU 计算内核 + RISE 计算平台 + RhinoVLA 模型：RPU 为多模态感知、任务理解、推理决策与动作生成提供算力；RISE 基于自研“光至 R1”芯片，算力达 500 TOPS；RhinoVLA 提供标准化预训练基础模型与完整开发流水线。量产方案覆盖具身智能、L4 无人物流车、乘用车智能辅助驾驶三大市场。\\n【团队】创始人、董事长兼 CEO 徐宁仪，清华电子工程系本硕博，曾任微软亚洲研究院硬件计算组组长、百度智能芯片部主任架构师，主导设计国内首款同时支持训练与推理的云端 AI 芯片“昆仑”；并任上海交大清源研究院长聘教授。联合创始人章健勇曾任蔚来汽车自动驾驶助理副总裁，主导 EyeQ4 与 Orin 平台的全球首发量产；联合创始人贺光辉为上海交大教授，研究方向为 AI 芯片与体系结构。核心团队超 200 人，平均 10 年以上经验。\\n【产品与落地】光至 R1 采用通用可编程架构，配套软件体系覆盖模型框架、编译器、算子库、Runtime、中间件、操作系统、仿真与实时控制；Huixi Embodied 算力产品系列面向机器人。搭载光至 R1 的计算平台已应用于智元精灵 G2 机器人，在连续产线直播作业中任务成功率达 99.99%——这是国内具身智能芯片少见的“真实场景连续作业”数据。\\n【融资】2026-10 完成 Pre-B+ 及 B 轮，合计约 17 亿元；2026 年内累计股权融资超 25 亿元。本轮由顺禧基金（北京市人工智能产业投资基金）领投，北京机器人产业发展投资基金、国智投、京国瑞、隐山资本、正心谷资本、金浦投资、建投投资、华泰宝利、慧目圆轮、上河动量基金等参与；老股东顺为资本、元生资本、凯辉基金、商汤国香资本、博华产投、国汽投资、朗玛峰创投、三七互娱、盛奕资本、星连资本、卓源亚洲持续加码。资金用于新一代具身智能大算力芯片研发、规模化交付与生态建设。\\n【风险】① 具身智能芯片赛道竞争激烈（英伟达 Jetson/Thor、地平线、黑芝麻、寒武纪均在做），价格与生态双重挤压；② 客户集中度高，目前公开的核心落地是智元一家，若其出货不及预期则产能空转；③ 500 TOPS 为峰值算力口径，实际有效算力与能效需第三方验证；④ 团队以自动驾驶背景为主，机器人场景的长期可靠性尚未经过多客户验证；⑤ 估值未披露，年内融资 25 亿元对应收入规模未知。\\n【观察指标】智元之外的第二、第三个量产客户；光至 R2 流片与算力提升幅度；L4 无人物流车的实际交付量；RhinoVLA 模型是否对外开放形成生态。", "listed": false, "funding": [{"inv": "顺禧基金（北京市人工智能产业投资基金）领投；北京机器人产业发展投资基金、国智投、京国瑞、隐山资本、正心谷、金浦、建投、华泰宝利、顺为、元生、凯辉、商汤国香、博华、国汽、朗玛峰、三七互娱等", "date": "2026-10", "round": "Pre-B+ 及 B 轮", "amount": "约17亿元"}], "industry": "semiconductor", "latestTech": "光至 R1（500 TOPS）量产上车智元精灵 G2，连续产线作业成功率 99.99%；新一代大算力芯片在研", "lastFunding": "2026-10", "latestFunding": "2026-10 · Pre-B+ 及 B 轮约 17 亿元（年内累计超 25 亿元）"}}$json$::jsonb
);